End Sub
</code></pre>
<p>Top populate layer 2 after layer 1 has been selected.</p>
<pre class="lang-vb prettyprint-override"><code>Private Sub ComboBox1_Change()

    Dim Route As Integer
    Dim Conveyor As Variant
    Dim RouteSelect As Variant
    Dim N As Integer

    ComboBox2 = &quot;&quot;
    ComboBox3 = &quot;&quot;
    Do While ComboBox2.ListCount &gt; 0
        ComboBox2.RemoveItem (0)
    Loop

    Do While ComboBox3.ListCount &gt; 0
        ComboBox3.RemoveItem (0)
    Loop

    ComboBox2.Clear
    ComboBox3.Clear

    Set tbl2 = ThisWorkbook.Worksheets(&quot;AllRoutes&quot;).ListObjects(&quot;AllRoutesTable&quot;)

    RouteSelect = ComboBox1.Value

    RouteSelect = Mid(RouteSelect, 2)


    For N = 1 To (tbl2.DataBodyRange.Rows.Count)

    Route = tbl2.DataBodyRange(N, 1).Value

    Conveyor = tbl2.DataBodyRange(N, 2).Value

    If RouteSelect = Route Then

    If Conveyor &lt;&gt; ConveyorLast Then
    With ComboBox2
            .AddItem Conveyor
    End With

    End If
    End If

    ConveyorLast = Conveyor

    Next


End Sub
</code></pre>
<p>To populate layer 3 after layer 2 has been selected.</p>
<pre class="lang-vb prettyprint-override"><code>Private Sub ComboBox2_Change()
    Dim Route As Integer
    Dim Conveyor As Variant
    Dim RecordReference As Variant
    Dim N As Integer

    ComboBox3 = &quot;&quot;

    Do While ComboBox3.ListCount &gt; 0
        ComboBox3.RemoveItem (0)
    Loop

    Set tbl2 = ThisWorkbook.Worksheets(&quot;AllRoutes&quot;).ListObjects(&quot;AllRoutesTable&quot;)

    ConveyorSelect = ComboBox2.Value

    For N = 1 To (tbl2.DataBodyRange.Rows.Count)

    Conveyor = tbl2.DataBodyRange(N, 2).Value

    RecordReference = tbl2.DataBodyRange(N, 3).Value

    If ConveyorSelect = Conveyor Then


    With ComboBox3
            .AddItem RecordReference
    End With

    End If
    Next


End Sub
</code></pre>
<p>I have essentially made code that loops through the big list I have shown in my original question and looks for which rows contain the wanted information.</p>
